const http = require('http');
const crypto = require('crypto');

class ConnectionPool {
  constructor() {
    this.connections = new Map();
    this.messageQueues = new Map();
    this.shutdownState = { initiated: false, drainPromise: null };
  }

  addConnection(id, socket) {
    this.connections.set(id, socket);
    this.messageQueues.set(id, []);
  }

  removeConnection(id) {
    this.connections.delete(id);
    this.messageQueues.delete(id);
  }

  getConnection(id) {
    return this.connections.get(id);
  }

  getAllIds() {
    return Array.from(this.connections.keys());
  }
}

class ChatServer {
  constructor(port) {
    this.port = port;
    this.pool = new ConnectionPool();
    this.broadcastTimers = new Map();
    this.server = null;
    this.shutdownCallbacks = [];
  }

  start() {
    this.server = http.createServer((req, res) => {
      res.writeHead(200);
      res.end('Chat server running');
    });

    this.server.on('upgrade', (req, socket, head) => {
      const connId = crypto.randomUUID();
      this.pool.addConnection(connId, socket);
      this.setupMessageHandler(connId, socket);
      this.scheduleHeartbeat(connId);

      socket.on('close', () => {
        this.cleanupConnection(connId);
      });
    });

    this.server.listen(this.port);
    this.registerShutdownHooks();
  }

  setupMessageHandler(connId, socket) {
    socket.on('data', (data) => {
      const message = data.toString();
      this.broadcastMessage(connId, message);
    });
  }

  broadcastMessage(senderId, message) {
    const recipients = this.pool.getAllIds().filter(id => id !== senderId);
    const payload = JSON.stringify({
      from: senderId,
      content: message,
      timestamp: Date.now()
    });

    for (const recipientId of recipients) {
      this.scheduleDeferredSend(recipientId, payload);
    }
  }

  scheduleDeferredSend(recipientId, payload) {
    const connection = this.pool.getConnection(recipientId);
    if (!connection) return;

    const timer = setTimeout(() => {
      this.executeSend(connection, payload, recipientId);
    }, 50);

    this.broadcastTimers.set(recipientId, timer);
  }

  executeSend(socketRef, payload, recipientId) {
    if (this.pool.shutdownState.initiated) {
      this.enqueueForDrain(socketRef, payload, recipientId);
      return;
    }
    try {
      socketRef.write(payload + '\n');
    } catch (e) {
      this.cleanupConnection(recipientId);
    }
  }

  enqueueForDrain(socketRef, payload, recipientId) {
    const drainCallback = () => {
      try {
        socketRef.write(payload + '\n');
        socketRef.end();
      } catch (e) {
        // socket already gone
      }
    };
    this.shutdownCallbacks.push(drainCallback);
  }

  scheduleHeartbeat(connId) {
    const interval = setInterval(() => {
      const conn = this.pool.getConnection(connId);
      if (conn) {
        try {
          conn.write('PING\n');
        } catch (e) {
          this.cleanupConnection(connId);
          clearInterval(interval);
        }
      } else {
        clearInterval(interval);
      }
    }, 30000);
  }

  cleanupConnection(connId) {
    const timer = this.broadcastTimers.get(connId);
    if (timer) {
      clearTimeout(timer);
      this.broadcastTimers.delete(connId);
    }
    this.pool.removeConnection(connId);
  }

  registerShutdownHooks() {
    const gracefulShutdown = () => {
      this.pool.shutdownState.initiated = true;

      this.server.close(() => {
        this.pool.shutdownState.drainPromise = this.drainConnections();
        this.pool.shutdownState.drainPromise.then(() => {
          process.exit(0);
        });
      });

      setTimeout(() => {
        process.exit(1);
      }, 10000);
    };

    process.on('SIGTERM', gracefulShutdown);
    process.on('SIGINT', gracefulShutdown);
  }

  async drainConnections() {
    const ids = this.pool.getAllIds();
    for (const id of ids) {
      const conn = this.pool.getConnection(id);
      if (conn) {
        try {
          conn.write('SERVER_SHUTDOWN\n');
        } catch (e) {}
      }
    }

    for (const id of ids) {
      this.cleanupConnection(id);
    }

    await new Promise(resolve => setTimeout(resolve, 1000));

    for (const cb of this.shutdownCallbacks) {
      cb();
    }
  }
}

const server = new ChatServer(8080);
server.start();
